// === Tab: mySketch ===
/*---------------------------------------------------
   Surreal Sediments – Rock Prototype (p5.js + WebGL) 
   2025-06-16
---------------------------------------------------*/
let rockShader;
let rotX = 0, rotY = 0, zoom = 1;

function preload() {
  /* ---------- Vertex Shader ---------- */
  const vtx = `
precision mediump float;

attribute vec3 aPosition;
attribute vec3 aNormal;

uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;
uniform float uTime;

varying vec3 vNormal;
varying vec3 vPos;

/* -------- 3D simplex noise (Ashima) -------- */
vec4 mod289(vec4 x){return x - floor(x*(1.0/289.0))*289.0;}
vec3 mod289(vec3 x){return x - floor(x*(1.0/289.0))*289.0;}
vec4 permute(vec4 x){return mod289(((x*34.0)+1.0)*x);}
vec4 taylorInvSqrt(vec4 r){return 1.79284291400159 - 0.85373472095314*r;}

float snoise(vec3 v){
  const vec2 C = vec2(1.0/6.0, 1.0/3.0);
  const vec4 D = vec4(0.0,0.5,1.0,2.0);
  vec3 i = floor(v + dot(v, C.yyy));
  vec3 x0 = v - i + dot(i, C.xxx);
  vec3 g = step(x0.yzx, x0.xyz);
  vec3 l = 1.0 - g;
  vec3 i1 = min(g.xyz, l.zxy);
  vec3 i2 = max(g.xyz, l.zxy);
  vec3 x1 = x0 - i1 +   C.xxx;
  vec3 x2 = x0 - i2 +   C.yyy;
  vec3 x3 = x0 -  D.yyy;
  i = mod289(i);
  vec4 p = permute( permute( permute(
            i.z + vec4(0.0, i1.z, i2.z, 1.0))
          + i.y + vec4(0.0, i1.y, i2.y, 1.0))
          + i.x + vec4(0.0, i1.x, i2.x, 1.0));
  vec4 j = p - 49.0 * floor(p / 49.0);
  vec4 x_ = floor(j / 7.0);
  vec4 y_ = floor(j - 7.0 * x_);
  vec4 x = (x_ *2.0 + 0.5)/7.0 - 1.0;
  vec4 y = (y_ *2.0 + 0.5)/7.0 - 1.0;
  vec4 h = 1.0 - abs(x) - abs(y);
  vec4 b0 = vec4(x.xy, y.xy);
  vec4 b1 = vec4(x.zw, y.zw);
  vec4 s0 = floor(b0)*2.0 + 1.0;
  vec4 s1 = floor(b1)*2.0 + 1.0;
  vec4 sh = -step(h, vec4(0.0));
  vec4 a0 = b0.xzyw + s0.xzyw*sh.xxyy;
  vec4 a1 = b1.xzyw + s1.xzyw*sh.zzww;
  vec3 g0 = vec3(a0.xy,h.x);
  vec3 g1 = vec3(a0.zw,h.y);
  vec3 g2 = vec3(a1.xy,h.z);
  vec3 g3 = vec3(a1.zw,h.w);
  vec4 norm = taylorInvSqrt(vec4(dot(g0,g0),dot(g1,g1),
                                 dot(g2,g2),dot(g3,g3)));
  g0 *= norm.x; g1 *= norm.y; g2 *= norm.z; g3 *= norm.w;
  vec4 m = max(0.6 - vec4(dot(x0,x0), dot(x1,x1),
                          dot(x2,x2), dot(x3,x3)), 0.0);
  m = m*m;
  return 42.0 * dot(m*m, vec4(dot(g0,x0), dot(g1,x1),
                              dot(g2,x2), dot(g3,x3)));
}
/* -------------------------------------------- */

void main(){
  float disp = snoise(aPosition*1.6 + vec3(uTime*0.2));
  vec3 newPos = aPosition + normalize(aNormal) * disp * 0.7;

  vNormal = mat3(uModelViewMatrix) * aNormal;
  vPos    = (uModelViewMatrix * vec4(newPos,1.0)).xyz;
  gl_Position = uProjectionMatrix * vec4(vPos,1.0);
}`;

  /* ---------- Fragment Shader ---------- */
  const frag = `
precision mediump float;
varying vec3 vNormal;
varying vec3 vPos;

void main(){
  // 基礎灰度
  float base = dot(normalize(vNormal), vec3(0.0,0.5,0.8))*0.5 + 0.5;
  vec3 col   = vec3(base)*0.7;

  // 紅色 rim-light
  float rim = pow(1.0 - abs(dot(normalize(vNormal), normalize(-vPos))), 2.0);
  col = mix(col, vec3(0.0,1.05,0.12), rim);

  gl_FragColor = vec4(col,1.0);
}`;

  rockShader = createShader(vtx, frag);
}

function setup() {
  createCanvas(1000, 750, WEBGL);
  noStroke();
  shader(rockShader);
}

function draw() {
  background(18);
  rockShader.setUniform('uTime', millis()/1000.0);
  if (keyIsPressed)  save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg")

  rotateX(rotX);
  rotateY(rotY);
  scale(zoom);

  /* 以高細分球體作 base mesh，Shader 內部位移成岩石 */
  sphere(200, 200, 200);
}

/* ---- 基本互動 ---- */
function mouseDragged(){
  if (mouseButton === LEFT){
    rotY += movedX * 0.01;
    rotX -= movedY * 0.01;
  }
}
function mouseWheel(e){
  zoom *= (e.delta > 0) ? 0.9 : 1.1;
  return false;
}

